namespace Morphant.Generator.UnitTests.TemplateModeTests;

internal static class TemplateModeExpectedSources
{
    public static string EmptyTemplateType(
        string destinationName)
    {
        return $$"""
                 // <auto-generated />
                 #nullable enable

                 namespace TestCase.Morphant.Generated
                 {
                     /// <summary>
                     /// Represents the Morphant mapping template for <see cref="global::TestCase.{{destinationName}}"/>.
                     /// </summary>
                     internal sealed record {{destinationName}}MorphantTemplate
                     {
                         /// <summary>
                         /// Creates a destination instance using convention-based mapping.
                         /// </summary>
                         /// <param name="marker">Selects convention-based mapping.</param>
                         public {{destinationName}}MorphantTemplate(global::Morphant.Markers.ByConventionMarker marker)
                         {
                         }

                         /// <summary>
                         /// Creates a destination instance using factory-based destination construction.
                         /// </summary>
                         /// <param name="marker">Selects factory-based construction.</param>
                         public {{destinationName}}MorphantTemplate(global::Morphant.Markers.IByFactoryMarker<global::TestCase.{{destinationName}}> marker)
                         {
                         }

                         /// <summary>
                         /// Creates a destination instance using a corresponding constructor.
                         /// </summary>
                         public {{destinationName}}MorphantTemplate()
                         {
                         }

                         public bool Equals({{destinationName}}MorphantTemplate? other) => false;

                         public override int GetHashCode() => 0;

                         public override string ToString() => string.Empty;

                         private bool PrintMembers(global::System.Text.StringBuilder builder) => false;
                     }
                 }
                 """;
    }

    public static string GenericExtension(
        string destinationType,
        string existingDestinationType,
        string templateResultType)
    {
        return $$"""
                 // <auto-generated />
                 #nullable enable

                 namespace Morphant
                 {
                     internal static partial class MorphantGeneratedTemplateExtensions
                     {
                         /// <summary>
                         /// Configures a mapping template.
                         /// </summary>
                         /// <typeparam name="TSource">The source type.</typeparam>
                         /// <param name="builder">The mapping builder to configure.</param>
                         /// <param name="template">
                         /// A lambda expression that receives the non-null source value and describes the mapping.
                         /// </param>
                         /// <returns>The <paramref name="builder"/> instance.</returns>
                         public static global::Morphant.MapperBuilder<TSource, {{destinationType}}> Template<TSource>(
                             this global::Morphant.MapperBuilder<TSource, {{destinationType}}> builder,
                             global::System.Func<TSource, {{templateResultType}}> template)
                             => throw new global::Morphant.Exceptions.RuntimeInvocationNotSupportedException();

                         /// <summary>
                         /// Configures a mapping template that depends on the destination's previous state.
                         /// </summary>
                         /// <typeparam name="TSource">The source type.</typeparam>
                         /// <param name="builder">The mapping builder to configure.</param>
                         /// <param name="template">
                         /// A lambda expression that receives the non-null source value and the destination's
                         /// previous value and describes the mapping. The previous value is
                         /// <see langword="default"/> when no destination exists.
                         /// </param>
                         /// <returns>The <paramref name="builder"/> instance.</returns>
                         public static global::Morphant.MapperBuilder<TSource, {{destinationType}}> Template<TSource>(
                             this global::Morphant.MapperBuilder<TSource, {{destinationType}}> builder,
                             global::System.Func<TSource, {{existingDestinationType}}, {{templateResultType}}> template)
                             => throw new global::Morphant.Exceptions.RuntimeInvocationNotSupportedException();
                     }
                 }
                 """;
    }

